import{_ as i,o as e,c as t,a2 as l}from"./chunks/framework.BqNd1sPY.js";const u=JSON.parse('{"title":"从这里开始","description":"","frontmatter":{},"headers":[],"relativePath":"00-从这里开始/index.md","filePath":"00-从这里开始/README.md"}'),r={name:"00-从这里开始/index.md"};function o(s,a,n,h,d,c){return e(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h1><h2 id="每天的固定动作" tabindex="-1">每天的固定动作 <a class="header-anchor" href="#每天的固定动作" aria-label="Permalink to &quot;每天的固定动作&quot;">​</a></h2><ol><li><strong>回忆 10 分钟</strong>：不看笔记，说出昨天的三个关键词。</li><li><strong>学习 45-70 分钟</strong>：先读直觉，再看数字例子，最后看公式。</li><li><strong>动手 20-40 分钟</strong>：运行或手算当天的小实验。</li><li><strong>闭卷 10 分钟</strong>：完成“今日验收”，答不上来就回看对应小节。</li><li><strong>写一句话</strong>：记录今天最容易混淆的概念。</li></ol><p>每天约 1.5-2.5 小时。第三周训练日可能需要额外等待计算完成，但等待不等于学习时间。</p><h2 id="三条学习规则" tabindex="-1">三条学习规则 <a class="header-anchor" href="#三条学习规则" aria-label="Permalink to &quot;三条学习规则&quot;">​</a></h2><ul><li>不背公式名称，先说清输入、动作和输出。</li><li>不用“<a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 下降了”代替“模型变好了”，还要看未参与训练的数据。</li><li>不追逐模型名和排行榜，先判断问题需要生成、检索、微调还是普通程序。</li></ul><h2 id="卡住时怎么做" tabindex="-1">卡住时怎么做 <a class="header-anchor" href="#卡住时怎么做" aria-label="Permalink to &quot;卡住时怎么做&quot;">​</a></h2><ul><li>看到数学符号：到 <a href="./../03-数学急救包/">数学急救包</a> 找同名概念。</li><li>术语太多：查 <a href="./../05-速查表/术语速查">术语速查</a>。</li><li>不知道选什么方法：查 <a href="./../05-速查表/方法选择">方法选择</a>。</li><li>代码报错：先读 <a href="./../05-速查表/训练排错">训练排错</a>，再保留完整报错和配置。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>每日验收题至少能独立答出 80%。第 14 天能画出训练全流程，第 21 天能重新运行项目并得到同量级指标，才算完成课程。</p>',10)])])}const m=i(r,[["render",o]]);export{u as __pageData,m as default};
